function readOnly(obj) {
  return new Proxy(obj, {
    set(target, key) {
      throw new TypeError(`cannot set ${String(key)}: read-only`);
    },
    deleteProperty(target, key) {
      throw new TypeError(`cannot delete ${String(key)}: read-only`);
    },
  });
}

unitTests:
test("reads pass through", () => {
  const original = { name: "Ada", tags: ["x"] };
  const view = readOnly(original);
  checkEq(view.name, "Ada");
  checkEq(Object.keys(view), ["name", "tags"]);
  original.name = "Grace";
  checkEq(view.name, "Grace");
});

test("changes are refused", () => {
  const original = { name: "Ada" };
  const view = readOnly(original);
  let message = "";
  try { view.name = "Bob"; } catch (e) { message = e.message; check(e instanceof TypeError, "should be a TypeError"); }
  check(message.includes("name"), "the message should name the property");
  checkThrows(() => { view.age = 3; }, TypeError);
  checkThrows(() => { delete view.name; }, TypeError);
  checkEq(original, { name: "Ada" });
});

